/* OUTSIDE IN THE CITY - exact logo (transparent, for dark backgrounds),
   embedded as a placeable image so flyers composite the real artwork. */
const OIC_LOGO_IMG = "data:image/png;base64,";
const OIC_LOGO_IMG_AR = 2.54237;  /* width / height */

/* Place the exact logo centred at cx, top at topY, given a width. */
function oicExactLogo(cx, topY, width) {
  var hh = width / OIC_LOGO_IMG_AR;
  return '<image x="' + (cx - width/2) + '" y="' + topY + '" width="' + width + '" height="' + hh +
    '" href="' + OIC_LOGO_IMG + '" xlink:href="' + OIC_LOGO_IMG + '" preserveAspectRatio="xMidYMid meet"/>';
}
if (typeof window !== 'undefined') { window.OIC_LOGO_IMG = OIC_LOGO_IMG; window.OIC_LOGO_IMG_AR = OIC_LOGO_IMG_AR; window.oicExactLogo = oicExactLogo; }
